impl Document {
    pub(crate) fn compare_asynchronous_server_call_point(
        &self,
        other: &Document,
        a: &AsynchronousServerCallPoint,
        b: &AsynchronousServerCallPoint,
        path: &str,
    ) -> Result<(), String> {
        self.compare_server_call_point(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_asynchronous_server_call_result_point(
        &self,
        other: &Document,
        a: &AsynchronousServerCallResultPoint,
        b: &AsynchronousServerCallResultPoint,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_access_point(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_asynchronous_server_call_point_ref() != b.get_asynchronous_server_call_point_ref()
        {
            return Err(format!(
                "{path}: ASYNCHRONOUS_SERVER_CALL_POINT_REF mismatch"
            ));
        }
        Ok(())
    }

    pub(crate) fn compare_server_call_point(
        &self,
        other: &Document,
        a: &ServerCallPoint,
        b: &ServerCallPoint,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_access_point(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_operation_i_ref() != b.get_operation_i_ref() {
            return Err(format!("{path}: OPERATION_I_REF mismatch"));
        }
        if a.get_timeout() != b.get_timeout() {
            return Err(format!("{path}: TIMEOUT mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_synchronous_server_call_point(
        &self,
        other: &Document,
        a: &SynchronousServerCallPoint,
        b: &SynchronousServerCallPoint,
        path: &str,
    ) -> Result<(), String> {
        self.compare_server_call_point(other, a.base(), b.base(), path)?;
        if a.get_called_from_within_exclusive_area_ref()
            != b.get_called_from_within_exclusive_area_ref()
        {
            return Err(format!(
                "{path}: CALLED_FROM_WITHIN_EXCLUSIVE_AREA_REF mismatch"
            ));
        }
        Ok(())
    }
}
